import { icons } from "lucide-react";
import type { SelectField } from "@/registry/default/lib/fields";
import selectEnumField from "@/registry/default/lib/fields/selectEnum/config";

export default function iconField(props?: Partial<SelectField>): SelectField {
	return selectEnumField<typeof icons>(icons, {
		name: "icon",
		interfaceName: "IconField",
		useKeyAsValue: true,
		admin: {
			components: {
				Field: "@/registry/default/lib/fields/icon",
			},
		},
		...props,
	});
}

"use client";

import { Check, ChevronsUpDown, icons } from "lucide-react";
import type { OptionObject, SelectFieldClientProps } from "payload";
import { useField } from "@payloadcms/ui";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/registry/ui/command";

import { Popover, PopoverContent, PopoverTrigger } from "@/registry/ui/popover";
import { cn } from "@/registry/default/utils";
import { useState, type Dispatch, type SetStateAction } from "react";
import { Button } from "@/registry/ui/button";

type IconName = keyof typeof icons;

function Icon({
  icon,
  index,
  value,
  setValue,
  setOpen,
}: {
  icon: OptionObject;
  index: number;
  value: IconName;
  setValue: (val: unknown, disableModifyingForm?: boolean) => void;
  setOpen: Dispatch<SetStateAction<boolean>>;
}) {
  const SelectIcon = icons[icon.value as IconName];
  return (
    <CommandItem
      value={icon.value}
      onSelect={(currentValue) => {
        setValue(currentValue === value ? "" : currentValue);
        setOpen(false);
      }}
      key={`${index}-${icon.value}`}
      className="cursor-pointer transition-colors duration-400 hover:bg-neutral-300"
    >
      <SelectIcon />
      {icon.value}
      <Check
        className={cn(
          "ml-auto opacity-0",
          value === icon.label && "opacity-100",
        )}
      />
    </CommandItem>
  );
}

export default function IconField({ field, path }: SelectFieldClientProps) {
  const { value, setValue } = useField<IconName>({ path });
  const [open, setOpen] = useState(false);
  const SelectIcon = icons[value];

  return (
    <div className="">
      <label>
        {field.label as string}
        {field.required ? <span className="pl-1 text-red-500">*</span> : ""}
      </label>
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild className="mt-2 w-full cursor-pointer">
          <Button
            variant="outline"
            role="combobox"
            aria-expanded={open}
            className="justify-between"
          >
            {SelectIcon && <SelectIcon />}
            {value ? value : "Select Icon..."}
            <ChevronsUpDown className="opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-[var(--radix-popover-trigger-width)] bg-neutral-200 dark:bg-neutral-600">
          <Command value={value}>
            <CommandInput
              placeholder="Search Icons..."
              className="border-none"
            />
            <CommandList>
              <CommandEmpty>No Icons Found.</CommandEmpty>
              <CommandGroup>
                {field.options.map((icon, index) => (
                  <Icon
                    key={`${index}-${(icon as OptionObject).value}`}
                    icon={icon as OptionObject}
                    index={index}
                    value={value}
                    setValue={setValue}
                    setOpen={setOpen}
                  />
                ))}
              </CommandGroup>
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
    </div>
  );
}
